"""Job structure, event schema and whole-request policy budgets."""
import re

from syntax import PolicyError, parse

__all__ = ['Invalid', 'Job', 'validate_job', 'LIMITS', 'NAME_FORM']

U32 = 4294967295
LIMITS = {'images': 16, 'cells': 262144, 'units': 1024, 'contexts': 32768,
          'connections': 4096, 'packets': 32768, 'files': 8192}
NAME_FORM = re.compile(r'[A-Za-z][A-Za-z0-9]{0,23}')

MAX_EVENTS = 200000
MAX_STAGES = 16
MAX_POLICY_BYTES = 8 * 1024 * 1024
MAX_ATOMS = 32768
MAX_PATH_SERVICES = 65536

SCHEMA = {
    'stage': {'epoch': 'positive', 'policy': 'text'},
    'commit': {'epoch': 'positive'},
    'retire': {'epoch': 'positive'},
    'spawn': {'unit': 'unit', 'service': 'name'},
    'clone': {'parent': 'unit', 'child': 'unit'},
    'exit': {'unit': 'unit'},
    'begin': {'unit': 'unit', 'rid': 'positive'},
    'finish': {'unit': 'unit', 'rid': 'positive'},
    'open': {'connection': 'pair'},
    'close': {'connection': 'pair'},
    'send': {'unit': 'unit', 'rid': 'positive', 'connection': 'pair',
             'stream': 'positive', 'destination': 'name'},
    'recv': {'connection': 'pair', 'stream': 'positive', 'unit': 'unit',
             'rid': 'positive', 'wire': 'wire'},
    'store': {'unit': 'unit', 'rid': 'positive', 'file': 'pair'},
    'load': {'file': 'pair', 'unit': 'unit', 'rid': 'positive'},
    'unlink': {'file': 'pair'},
    'inspect': {},
}


class Invalid(ValueError):
    """The job (or the whole request) is structurally out of contract."""


def _integer(value, low=1, high=U32):
    # Booleans are not integers: the contract insists on the exact type.
    return type(value) is int and low <= value <= high


def _typed(value, kind):
    if kind == 'positive':
        return _integer(value)
    if kind == 'name':
        return type(value) is str and NAME_FORM.fullmatch(value) is not None
    if kind == 'text':
        if type(value) is not str:
            return False
        value.encode('utf-8')          # an unpaired surrogate makes the job invalid
        return True
    if kind == 'wire':
        return value is None or (type(value) is str and len(value) <= 96)
    if kind == 'pair':
        return type(value) is list and len(value) == 2 and all(_integer(item) for item in value)
    if kind == 'unit':
        return (type(value) is list and len(value) == 3 and _integer(value[0], 0)
                and _integer(value[1]) and _integer(value[2]))
    return False


class Job:
    """A structurally valid job plus the request budget it consumes."""

    __slots__ = ('services', 'limits', 'events', 'policy_bytes', 'stages', 'atoms', 'symbols')

    def __init__(self, services, limits, events, policy_bytes, stages, atoms, symbols):
        self.services = services
        self.limits = limits
        self.events = events
        self.policy_bytes = policy_bytes
        self.stages = stages
-----
        self.symbols = 0
        self.nonliteral = set()
        self.complex = 0
        self.rules = []

    def fail(self, what):
        raise PolicyError(what)

    def predicate(self, depth):
        if depth > MAX_DEPTH:
            self.fail('predicate depth')
        if self.index >= len(self.tokens):
            self.fail('predicate')
        token = self.tokens[self.index]
        if token == '(':
            self.index += 1
            left = self.predicate(depth + 1)
            operator = self.tokens[self.index] if self.index < len(self.tokens) else None
            if operator not in ('and', 'or'):
                self.fail('binary operator')
            self.index += 1
            right = self.predicate(depth + 1)
            if self.tokens[self.index:self.index + 1] != [')']:
                self.fail('closing parenthesis')
            self.index += 1
            return (operator, left, right)
        if token == 'not':
            self.index += 1
            if self.tokens[self.index:self.index + 1] != ['(']:
                self.fail('not parenthesis')
            self.index += 1
            inner = self.predicate(depth + 1)
            if self.tokens[self.index:self.index + 1] != [')']:
                self.fail('closing parenthesis')
            self.index += 1
            return ('not', inner)
        if token not in ATOM_KINDS:
            self.fail('atom')
        self.index += 1
        if self.tokens[self.index:self.index + 1] != ['(']:
            self.fail('atom parenthesis')
        self.index += 1
        path = self.path()
        if self.tokens[self.index:self.index + 1] != [')']:
            self.fail('closing parenthesis')
        self.index += 1
        if len(path) > MAX_PATH:
            self.fail('path length')
        self.atoms += 1
        self.symbols += len(path)
        if token != 'match':
            if len(path) > MAX_NONLITERAL_PATH:
                self.fail('nonliteral path length')
            self.nonliteral.add((token, path))
        return (token, path)

    def path(self):
        path = []
        tokens = self.tokens
        index = self.index
        while index < len(tokens) and tokens[index] != ')':
            token = tokens[index]
            if token in _KEYWORDS or token in '();,':
                self.fail('path name')
            path.append(token)
            if len(path) > MAX_PATH:
                self.fail('path length')
            index += 1
            if index < len(tokens) and tokens[index] == ',':
                index += 1
                if index >= len(tokens) or tokens[index] in '();,' or tokens[index] in _KEYWORDS:
                    self.fail('path name')
                continue
            break
        self.index = index
        return tuple(path)

    def run(self):
        tokens = self.tokens
        while self.index < len(tokens):
            predicate = self.predicate(1)
            action = tokens[self.index] if self.index < len(tokens) else None
            if action not in ('allow', 'drop'):
                self.fail('action')
            self.index += 1
            if tokens[self.index:self.index + 1] != [';']:
                self.fail('rule terminator')
            self.index += 1
            if predicate[0] != 'match':
                self.complex += 1
                if self.complex > MAX_COMPLEX_RULES:
                    self.fail('complex rule count')
                if rule_atoms(predicate) > MAX_COMPLEX_ATOMS:
                    self.fail('complex rule atoms')
            if self.atoms > MAX_ATOMS or self.symbols > MAX_PATH_SERVICES:
                self.fail('occurrence budget')
            if len(self.nonliteral) > MAX_DISTINCT_NONLITERAL:
                self.fail('distinct nonliteral atoms')
            self.rules.append((predicate, action == 'allow'))
        if self.index != len(tokens):
            self.fail('trailing input')
        return self.rules, self.atoms, self.symbols


def parse(text):
    """Return ``(rules, atom_occurrences, path_service_occurrences)``.

    ``rules`` is a list of ``(predicate, allow)`` pairs; a predicate is a nested
    tuple whose leaves are ``(kind, path)`` with ``path`` a tuple of service
    names.  Raises PolicyError for syntax and policy-bound violations.
    """
    if type(text) is not str:
        raise PolicyError('policy type')
    try:
        text.encode('utf-8')
    except UnicodeEncodeError as exc:
        raise PolicyError('surrogate') from exc
    return _Parser(_tokenize(text)).run()


